import csv
import datetime
import decimal
import json
import os
import sys

def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None

    # Try Excel serial date
    try:
        num = float(val)
        if 10000 <= num <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(num))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    formats = (
        "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d",
        "%m-%d-%Y", "%d-%m-%Y", "%Y%m%d",
        "%B %d, %Y", "%b %d, %Y", "%d-%b-%Y", "%d-%B-%Y"
    )
    for fmt in formats:
        try:
            return datetime.datetime.strptime(val, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass

    return None

def parse_amount(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    cleaned = val.replace("$", "").replace(",", "").strip()
    try:
        d = decimal.Decimal(cleaned)
        if d == d.to_integral_value():
            return str(d.to_integral_value())
        else:
            s = f"{d:f}"
            if "." in s:
                s = s.rstrip("0").rstrip(".")
            return s
    except Exception:
        return None

FACT_RULES = {
    "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
    "end date": ("lca_disclosure", "END_DATE", "date"),
}

def load_lca_disclosure(packet_dir):
    data = {}
    doc_name = "lca_disclosure"
    filename = None
    for fname in os.listdir(packet_dir):
        base, ext = os.path.splitext(fname)
        if base == doc_name and ext.lower() in [".csv", ".tsv", ".txt"]:
            filename = os.path.join(packet_dir, fname)
            break

    if not filename or not os.path.isfile(filename):
        return data

    with open(filename, mode="r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            case_num = row.get("CASE_NUMBER")
            if not case_num:
                continue
            case_num = case_num.strip()
            if case_num not in data:
                data[case_num] = []
            data[case_num].append(row)

    return data

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    lca_data = load_lca_disclosure(packet_dir)

    results = {}
    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity_id = pair.split("::", 1)
        needed_facts = facts_spec.get(rule_id, [])

        pair_result = {}
        rows = lca_data.get(entity_id, [])

        for fact in needed_facts:
            rule_info = FACT_RULES.get(fact)
            if not rule_info:
                pair_result[fact] = "ABSENT"
                continue

            doc, col, val_type = rule_info
            values = set()

            for row in rows:
                raw_val = row.get(col)
                if val_type == "amount":
                    parsed = parse_amount(raw_val)
                elif val_type == "date":
                    parsed = parse_date(raw_val)
                else:
                    parsed = str(raw_val).strip() if raw_val else None

                if parsed is not None:
                    values.add(parsed)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                val = next(iter(values))
                pair_result[fact] = [val, doc]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
