import sys
import os
import json
import csv
import datetime
from collections import defaultdict


def parse_date(val):
    if not val:
        return None
    val = str(val).strip()
    if not val:
        return None

    # Check for Excel serial number
    try:
        f = float(val)
        if 1000 <= f <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(f)))
            return d.strftime('%Y-%m-%d')
    except ValueError:
        pass

    # Try common date string formats
    formats = [
        '%Y-%m-%d',
        '%m/%d/%Y',
        '%d/%m/%Y',
        '%Y/%m/%d',
        '%m-%d-%Y',
        '%d-%m-%Y',
        '%B %d, %Y',
        '%b %d, %Y',
        '%b. %d, %Y'
    ]
    candidates = [val]
    if ' ' in val:
        candidates.append(val.split()[0])
    if 'T' in val:
        candidates.append(val.split('T')[0])

    for cand in candidates:
        for fmt in formats:
            try:
                d = datetime.datetime.strptime(cand, fmt).date()
                return d.strftime('%Y-%m-%d')
            except ValueError:
                pass

    return val


def clean_amount(val):
    if not val:
        return None
    val = str(val).strip()
    if not val:
        return None

    val = val.replace('$', '').replace(',', '').strip()
    if val.startswith('(') and val.endswith(')'):
        val = '-' + val[1:-1].strip()
    return val if val else None


def clean_text(val):
    if not val:
        return None
    val = str(val).strip()
    return val if val else None


FACT_MAPPING = {
    "offered wage": ("WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("PREVAILING_WAGE", "amount"),
    "begin date": ("BEGIN_DATE", "date"),
    "end date": ("END_DATE", "date"),
    "job title": ("JOB_TITLE", "text"),
    "soc code": ("SOC_CODE", "text"),
    "soc title": ("SOC_TITLE", "text"),
    "full time position": ("FULL_TIME_POSITION", "text"),
    "worksite city": ("WORKSITE_CITY", "text"),
    "worksite state": ("WORKSITE_STATE", "text"),
    "pw wage level": ("PW_WAGE_LEVEL", "text")
}


def find_csv_file(packet_dir, target_name="lca_disclosure.csv"):
    for root, _, files in os.walk(packet_dir):
        for fname in files:
            if fname.lower() == target_name.lower():
                return os.path.join(root, fname)
    return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    csv_path = find_csv_file(packet_dir, "lca_disclosure.csv")
    records_by_case = defaultdict(list)

    if csv_path and os.path.exists(csv_path):
        with open(csv_path, 'r', encoding='utf-8-sig', errors='replace') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_num = row.get("CASE_NUMBER", "").strip()
                if case_num:
                    records_by_case[case_num].append(row)

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        rule_facts = facts_by_rule.get(rule_id, [])
        output[pair] = {}

        entity_rows = records_by_case.get(entity, [])

        for fact in rule_facts:
            mapping = FACT_MAPPING.get(fact.lower())
            if not mapping:
                col_name = fact.upper().replace(" ", "_")
                val_type = "text"
            else:
                col_name, val_type = mapping

            values = set()
            for row in entity_rows:
                raw_val = row.get(col_name)
                if raw_val is not None:
                    if val_type == "date":
                        cleaned = parse_date(raw_val)
                    elif val_type == "amount":
                        cleaned = clean_amount(raw_val)
                    else:
                        cleaned = clean_text(raw_val)

                    if cleaned is not None and cleaned != "":
                        values.add(cleaned)

            if not values:
                output[pair][fact] = "ABSENT"
            elif len(values) == 1:
                output[pair][fact] = [next(iter(values)), "lca_disclosure"]
            else:
                if val_type == "amount":
                    try:
                        num_map = {float(v): v for v in values}
                        if len(num_map) == 1:
                            val = sorted(values, key=len)[0]
                            output[pair][fact] = [val, "lca_disclosure"]
                            continue
                    except ValueError:
                        pass
                output[pair][fact] = "CONFLICT"

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
